/*! html2canvas fallback stub for the RunBuddy demo */
(function (global) {
  function resolveDimension(value, fallback) {
    return Number.isFinite(value) && value > 0 ? value : fallback;
  }

  function getFallbackText(element) {
    if (!element) return '';
    const text = (element.innerText || element.textContent || '').trim();
    return text || element.tagName || 'RunBuddy report';
  }

  async function html2canvas(element, options) {
    options = options || {};

    if (!element) {
      throw new Error('html2canvas fallback received no element.');
    }

    const rect = typeof element.getBoundingClientRect === 'function'
      ? element.getBoundingClientRect()
      : { width: 393, height: 852 };

    const scale = resolveDimension(options.scale, 1);
    const width = resolveDimension(options.width, Math.round(rect.width) || element.clientWidth || 393);
    const height = resolveDimension(options.height, Math.round(rect.height) || element.clientHeight || 852);

    const canvas = document.createElement('canvas');
    canvas.width = Math.max(1, Math.round(width * scale));
    canvas.height = Math.max(1, Math.round(height * scale));

    const ctx = canvas.getContext('2d');
    if (!ctx) return canvas;

    ctx.scale(scale, scale);
    ctx.fillStyle = options.backgroundColor === null ? '#ffffff' : (options.backgroundColor || '#ffffff');
    ctx.fillRect(0, 0, width, height);

    const text = getFallbackText(element);
    const lines = text.split(/\r?\n/).map((line) => line.trim()).filter(Boolean);

    ctx.fillStyle = '#111111';
    ctx.font = '16px Arial, sans-serif';
    ctx.textBaseline = 'top';

    let y = 16;
    lines.slice(0, 40).forEach((line) => {
      ctx.fillText(line.slice(0, 80), 16, y);
      y += 22;
    });

    return canvas;
  }

  global.html2canvas = html2canvas;
})(window);
